package server

import (
	"os"
	"path/filepath"
	"strings"

	"yozakura/backend/pkg/brand"
)

// hyprUserConfig is the root of the user's hyprlang config; tests swap it.
var hyprUserConfig = func() string { return filepath.Join(xdgConfigDir(), "hypr", "hyprland.conf") }

// maxSourceDepth bounds `source =` nesting (and cycles) in userOverrides.
const maxSourceDepth = 8

// userOverrides returns the option keys (`general:gaps_in`) the user's
// hyprlang config sets again after it sources the generated file. Hyprland
// keeps the last value, so after a reload theirs wins; a live `keyword`
// would win instead until the next reload, so those keys must reload.
// It follows `source =` lines (globs, `~`, paths relative to the sourcing
// file) from root, in order. Files we generate (the backend's entry
// overlay, which re-applies the shell's own appearance after the generated
// file) do not count. Best effort: unreadable files are skipped.
func userOverrides(root, generated string) map[string]bool {
	w := overrideWalk{generated: filepath.Clean(generated), seen: map[string]bool{}, keys: map[string]bool{}}
	w.file(root, 0)
	return w.keys
}

type overrideWalk struct {
	generated string
	after     bool // the generated file was sourced already
	seen      map[string]bool
	keys      map[string]bool
}

func (w *overrideWalk) file(path string, depth int) {
	path = filepath.Clean(path)
	if depth > maxSourceDepth || w.seen[path] || path == w.generated {
		return
	}
	w.seen[path] = true
	data, err := os.ReadFile(path)
	if err != nil {
		return
	}
	text := string(data)
	ours := strings.HasPrefix(text, "# Generated by "+brand.DisplayName)
	var stack []string
	for _, raw := range strings.Split(text, "\n") {
		line := strings.TrimSpace(raw)
		switch {
		case line == "" || strings.HasPrefix(line, "#"):
		case strings.HasSuffix(line, "{"):
			stack = append(stack, strings.TrimSpace(strings.TrimSuffix(line, "{")))
		case line == "}":
			if len(stack) > 0 {
				stack = stack[:len(stack)-1]
			}
		default:
			i := strings.Index(line, "=")
			if i < 0 {
				continue
			}
			key := strings.TrimSpace(line[:i])
			value := strings.TrimSpace(line[i+1:])
			if len(stack) == 0 && key == "source" {
				w.source(value, filepath.Dir(path), depth)
				continue
			}
			if w.after && !ours && !strings.HasPrefix(key, "$") {
				w.keys[strings.Join(append(append([]string(nil), stack...), key), ":")] = true
			}
		}
	}
}

// source follows one `source = value` line.
func (w *overrideWalk) source(value, dir string, depth int) {
	if home, err := os.UserHomeDir(); err == nil && (value == "~" || strings.HasPrefix(value, "~/")) {
		value = filepath.Join(home, strings.TrimPrefix(value, "~"))
	}
	if !filepath.IsAbs(value) {
		value = filepath.Join(dir, value)
	}
	matches, err := filepath.Glob(value)
	if err != nil || len(matches) == 0 {
		matches = []string{value}
	}
	for _, m := range matches {
		if filepath.Clean(m) == w.generated {
			w.after = true
			continue
		}
		w.file(m, depth+1)
	}
}
